-- Itens do cardapio impresso que faltavam no sistema + precos das bebidas importadas das NFC-e.
-- Pode rodar mais de uma vez (ignora o que ja existe pelo nome).
SET NAMES utf8mb4;
START TRANSACTION;


-- Itens genericos antigos, agora separados em Tapioca/Cuscuz no cardapio impresso (so desativa, nao apaga)
UPDATE rest_itens_cardapio SET ativo=0 WHERE nome IN ('Carne de sol com queijo','Frango');

-- Precos das bebidas importadas (so onde ainda esta em R$ 0 e pausado) e liberacao para venda
UPDATE rest_itens_cardapio SET preco=13, pausado=0 WHERE nome LIKE 'Yopro 250ml%' AND preco=0 AND pausado=1;
